INSERT INTO "posts" ("slug", "kind", "category", "title", "excerpt", "body", "cover_file", "read_minutes", "author_name", "diseases", "tags",
  "seo_description", "featured", "status", "published_at", "updated_by")
SELECT $j$sa-dec-flower-half-marathon-2026-lo-trinh$j$, 'article', 'su-kien', $j$Sa Đéc Flower Half Marathon 2026: chi tiết 3 lộ trình 5 km, 10 km, 21 km qua Làng hoa Sa Đéc$j$,
  $j$Sa Đéc Flower Half Marathon 2026 diễn ra 25–27/12/2026 tại phường Sa Đéc, Đồng Tháp với 3 cự ly 5 km, 10 km và 21 km chạy xuyên phố hoa và Làng hoa Sa Đéc. Xem chi tiết lộ trình, sơ đồ Expo và các hoạt động hưởng ứng.$j$,
  $j$[{"type": "p", "text": "**Sa Đéc Flower Half Marathon 2026** – giải chạy bán marathon đầu tiên mang tên “xứ hoa” – sẽ diễn ra **từ ngày 25 đến 27/12/2026 tại phường Sa Đéc, tỉnh Đồng Tháp**, do UBND phường Sa Đéc chỉ đạo tổ chức. Với khẩu hiệu **“Chinh phục cung đường hoa”**, giải đưa runner chạy xuyên phố hoa, qua những cây cầu bắc ngang rạch Sa Đéc và men theo các vườn hoa của **Làng hoa Sa Đéc** – nơi Cây Cảnh Miền Tây đặt vườn ươm."}, {"type": "image", "file": "https://cdn.hstatic.net/files/200001224249/file/screenshot_2026-11-10_190334_e0e528a4dc20454f8bf36347580ce9cb.png", "caption": "Áp phích chính thức Sa Đéc Flower Half Marathon 2026 – 25–27/12/2026, phường Sa Đéc, Đồng Tháp (ảnh: Ban tổ chức)"}, {"type": "h2", "text": "Thông tin nhanh về giải chạy"}, {"type": "table", "rows": [["Hạng mục", "Thông tin"], ["Tên giải", "Sa Đéc Flower Half Marathon 2026 – “Hoa bên dòng Sa Giang”"], ["Thời gian", "25–27/12/2026 (ngày thi đấu chính: Chủ nhật 27/12/2026)"], ["Địa điểm", "Phường Sa Đéc, tỉnh Đồng Tháp"], ["Cự ly chính", "5 km · 10 km · 21 km (bán marathon)"], ["Xuất phát – về đích 10 km, 21 km", "Quảng trường Sa Đéc"], ["Xuất phát – về đích 5 km", "Cầu Rạch Sa Nhiên (Làng hoa Sa Đéc), xuất phát 6 giờ 40 ngày 27/12/2026"], ["Quy mô dự kiến", "Khoảng 7.000 vận động viên"], ["Hotline ban tổ chức", "0888 696 970 · sadecmarathon@gmail.com"]]}, {"type": "p", "text": "Cả ba cung đường đều có **độ cao thấp, ít dốc**, rất phù hợp cho người mới tập chạy lẫn runner muốn lập thành tích cá nhân. Điểm nhấn chung là chạy xuyên phố hoa và trải nghiệm Làng hoa Sa Đéc ngay trong buổi sáng cuối năm – mùa hoa Tết đang vào độ rực rỡ nhất."}, {"type": "h2", "text": "Sơ đồ đường chạy: 3 lộ trình qua xứ hoa"}, {"type": "h3", "text": "🌸 Cự ly 5 km – Dạo bước giữa Làng hoa Sa Đéc"}, {"type": "image", "file": "https://cdn.hstatic.net/files/200001224249/file/frame_6007583602__4__8be50b0f33544fef868a6fb31a6f160d.webp", "caption": "Lộ trình chi tiết cự ly 5 km – xuất phát 6h40 ngày 27/12/2026 tại Làng hoa Sa Đéc (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Cự ly 5 km là “cung đường đẹp nhất” cho gia đình, nhóm bạn và người mới chạy. Toàn bộ lộ trình nằm trong khu Làng hoa, xuất phát lúc **6 giờ 40 phút ngày 27/12/2026**:"}, {"type": "list", "ordered": true, "items": ["Xuất phát từ **Cầu Rạch Sa Nhiên**.", "Chạy theo **đường Cầu Rạch Sa Nhiên**.", "Rẽ vào **đường song song đường Hoa Sa Đéc** (hướng về ĐT 852B).", "Quay về **đường Hoa Sa Đéc** – đoạn đẹp nhất với hai bên là vườn hoa.", "Trở lại đường Cầu Rạch Sa Nhiên và **về đích tại Cầu Rạch Sa Nhiên**."]}, {"type": "p", "text": "Ba điểm nhấn trên đường: **(1) Làng hoa Sa Đéc** với sắc hoa rực rỡ, **(2) vườn hoa và tuyến đường hoa** ngập màu, **(3) không gian làng hoa** yên bình đúng chất miền Tây. Đây là cự ly lý tưởng để vừa chạy vừa chụp ảnh – nhớ chạy chậm lại ở đường Hoa Sa Đéc nhé!"}, {"type": "h3", "text": "🌼 Cự ly 10 km – Vòng quanh phố hoa Sa Đéc"}, {"type": "image", "file": "https://cdn.hstatic.net/files/200001224249/file/asset_3-100_1_78098bb7b8b546439d28b077db1e4817.webp", "caption": "Lộ trình chi tiết và độ cao tuyến đường cự ly 10 km (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Cự ly 10 km xuất phát và về đích tại **Quảng trường Sa Đéc**, chạy một vòng quanh trung tâm phường, qua ba cây cầu. Biểu đồ độ cao gần như phẳng, chỉ dao động quanh 0–15 m, chênh lên nhẹ ở các đầu cầu. Lộ trình chi tiết:"}, {"type": "list", "ordered": true, "items": ["Xuất phát tại Quảng trường Sa Đéc → rẽ phải đường **QL80B**, đi thẳng QL80B.", "Rẽ trái đường **Trần Thị Nhượng**, đi thẳng Trần Thị Nhượng.", "Rẽ phải đường **Hùng Vương** → đi thẳng qua **cầu Cái Sơn 3** → tiếp tục Hùng Vương → qua **cầu Rạch Rắn** → đi thẳng Hùng Vương.", "Rẽ phải đường **QL80** → qua **cầu Đốc Phủ Hiền** → đi thẳng QL80.", "Rẽ phải đường **QL80B**, đi thẳng QL80B.", "Rẽ phải đường **Nguyễn Sinh Sắc**, đi thẳng Nguyễn Sinh Sắc.", "Rẽ trái đường **Nguyễn Hữu Cảnh** → rẽ trái **đường số 5** → rẽ trái đường **Nguyễn Tất Thành**.", "Rẽ phải đường **Nguyễn Cư Trinh**, đi thẳng Nguyễn Cư Trinh → rẽ trái **về đích tại Quảng trường Sa Đéc**."]}, {"type": "p", "text": "Trên đường, runner đi ngang nhiều địa danh quen thuộc của Sa Đéc như khu **Nhà cổ Huỳnh Thủy Lê**, công viên Sa Đéc, chợ và các quán hủ tiếu nổi tiếng – một “tour” phố cũ thu nhỏ trong 10 km."}, {"type": "h3", "text": "🌺 Cự ly 21 km – Chinh phục trọn cung đường hoa"}, {"type": "image", "file": "https://cdn.hstatic.net/files/200001224249/file/asset_4-100_1_ad909c95f00f4d43a9e6584212aadeb9.webp", "caption": "Lộ trình chi tiết cự ly 21 km – bán marathon qua phố hoa và Làng hoa Sa Đéc (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Cự ly bán marathon 21 km là “trái tim” của giải: xuất phát và về đích tại **Quảng trường Sa Đéc**, chạy lên **cầu Sa Đéc 2**, xuyên qua **Làng hoa Sa Đéc**, rồi vòng về phố cũ. Lộ trình chi tiết:"}, {"type": "list", "ordered": true, "items": ["Xuất phát tại Quảng trường Sa Đéc → rẽ phải đường **QL80B**, đi thẳng QL80B.", "Rẽ trái đường **Trần Thị Nhượng**, đi thẳng → rẽ phải **ĐT 852B**, đi thẳng ĐT 852B.", "Qua **cầu Kênh KC1** → đi thẳng ĐT 852B → qua **cầu Sáu Hiếu** → đi thẳng ĐT 852B → qua **cầu Sa Đéc 2**.", "Rẽ phải đường **Cao Thắng** → rẽ trái **Làng hoa Sa Đéc** → đi thẳng **đường Hoa Sa Đéc**.", "Qua **cầu Cái Dao** → đi thẳng đường Hoa Sa Đéc → qua **cầu Sa Nhiên 1**.", "Rẽ phải vào **ĐQL 80B** → qua **cầu Nàng Hai** → đi thẳng ĐQL 80B.", "Rẽ trái đường **Ngô Gia Tự** → qua **cầu Trái Bí** → rẽ phải đường **Nguyễn Tất Thành**, đi thẳng.", "Rẽ trái đường **Trần Thị Nhượng** → rẽ phải đường **Hùng Vương** → qua **cầu Cái Sơn 3** → qua **cầu Rạch Rắn** → đi thẳng Hùng Vương.", "Rẽ phải đường **QL80** → qua **cầu Đốc Phủ Hiền** → đi thẳng QL80 → rẽ phải **QL80B**.", "Rẽ phải đường **Nguyễn Sinh Sắc** → rẽ trái **Nguyễn Hữu Cảnh** → rẽ trái **đường số 5** → rẽ trái **Nguyễn Tất Thành**.", "Rẽ phải đường **Nguyễn Cư Trinh**, đi thẳng → rẽ trái **về đích tại Quảng trường Sa Đéc**."]}, {"type": "p", "text": "Cung 21 km đi qua khoảng **10 cây cầu** – đặc sản của vùng sông nước – nên runner nên phân phối sức ở các đoạn lên cầu. Bù lại, đoạn chạy giữa Làng hoa (đường Cao Thắng – đường Hoa Sa Đéc – cầu Sa Nhiên 1) chính là khoảnh khắc “chinh phục cung đường hoa” đúng nghĩa."}, {"type": "note", "title": "Lưu ý cho runner", "text": "Lộ trình và giờ xuất phát là **dự kiến** theo thông tin ban tổ chức công bố, có thể điều chỉnh. Giờ xuất phát cự ly 10 km, 21 km và lịch nhận BIB vui lòng theo dõi trang chính thức sadecmarathon.com hoặc fanpage SaDecFlowerHalfMarathon. Mang theo giấy tờ tùy thân khi nhận BIB, khởi động kỹ và bổ sung nước tại các trạm."}, {"type": "h2", "text": "Lịch trình dự kiến – Trọn vẹn trải nghiệm xứ hoa"}, {"type": "p", "text": "Giải chạy kéo dài **3 ngày 25–27/12/2026**, không chỉ là một buổi chạy mà là cả một lễ hội:"}, {"type": "list", "ordered": false, "items": ["**Những ngày trước giờ chạy:** nhận BIB và bộ vật phẩm tại khu vực Expo, tham quan gian hàng OCOP – đặc sản, ẩm thực địa phương, chụp ảnh check-in.", "**Ngày thi đấu 27/12/2026:** các cự ly 21 km, 10 km và 5 km lần lượt xuất phát (5 km xuất phát 6h40 tại Làng hoa Sa Đéc).", "**Xuyên suốt sự kiện:** chuỗi hoạt động hưởng ứng – check-in, cosplay, liên hoan ẩm thực và đêm nhạc tuổi trẻ."]}, {"type": "h2", "text": "Các hoạt động hưởng ứng"}, {"type": "h3", "text": "📸 Check-in “Runner & Hoa”"}, {"type": "p", "text": "Khi bước chạy hòa cùng sắc hoa Sa Đéc: runner check-in tại các vườn hoa, tiểu cảnh và cổng làng hoa, gặp gỡ những người trồng hoa đã gắn bó cả đời với nghề. Một gợi ý từ nhà vườn: buổi sáng sớm, nắng xiên qua giàn hoa là lúc ảnh đẹp nhất."}, {"type": "h3", "text": "🎭 Cosplay “Rực rỡ sắc hoa Sa Nhiên”"}, {"type": "p", "text": "Runner được khuyến khích hóa trang theo chủ đề hoa – hoa hồng, hướng dương, cúc mâm xôi – hay nhân vật cổ tích, biến đường chạy thành một lễ hội đường phố đầy màu sắc."}, {"type": "h3", "text": "🍜 Liên hoan ẩm thực “Ẩm thực xứ hoa Sa Nhiên”"}, {"type": "p", "text": "Thưởng thức hương vị miền Tây đậm đà: **hủ tiếu Sa Đéc**, các món từ **làng bột Sa Đéc** và đặc sản địa phương ở khu “Chợ quê lên phố” ngay cạnh Expo."}, {"type": "h3", "text": "🎶 Đêm nhạc “Sôi động mùa hoa mới”"}, {"type": "p", "text": "Đêm nhạc tuổi trẻ bùng nổ cảm xúc giữa phố hoa Sa Đéc – nơi runner, du khách và người dân cùng hòa chung không khí trước và sau ngày chạy."}, {"type": "h2", "text": "Sơ đồ bố trí mặt bằng khu vực Expo"}, {"type": "image", "file": "https://cdn.hstatic.net/files/200001224249/file/frame_6007583602__5__71579536835941a3961fa2cb57df84c5.jpg", "caption": "Sơ đồ bố trí mặt bằng khu vực Expo dọc ĐQL80B (ảnh: Ban tổ chức)"}, {"type": "p", "text": "Khu Expo nằm dọc **ĐQL80B** (một đầu hướng Cao Lãnh, một đầu hướng Sa Đéc), vào bằng **cổng chào** ở giữa. Các khu vực chính:"}, {"type": "list", "ordered": false, "items": ["**Khu nhận BIB** riêng cho từng cự ly: 5 km, 10 km và 21 km.", "**Khu phục hồi** và **An Spa** cho runner sau khi chạy.", "**Quầy lưu niệm**, **tiểu cảnh check-in** và khu Ban tổ chức (BTC).", "**Không gian OCOP và đặc sản địa phương**.", "**Khu ẩm thực Làng bột Sa Đéc** (10 gian) và **khu ẩm thực địa phương “Chợ quê lên phố”** (10 gian).", "**Khu nhà tài trợ** (20 gian) hai bên cổng chào.", "**Sân khấu**, khu bàn ghế ngồi, nhà vệ sinh (WC) và **bãi đậu xe** lớn phía hướng Sa Đéc."]}, {"type": "h2", "text": "Ghé Cây Cảnh Miền Tây khi về Làng hoa Sa Đéc"}, {"type": "p", "text": "Cung đường 5 km và 21 km chạy ngang **Làng hoa Sa Đéc** – nơi đặt vườn ươm của Cây Cảnh Miền Tây. Sau khi về đích, bạn có thể ghé vườn tham quan, chụp ảnh và chọn cây hoa Tết mang về. Xem [hệ thống cửa hàng](/he-thong-cua-hang) hoặc gọi hotline để được hướng dẫn đường đi. Chúc các runner một mùa chạy rực rỡ sắc hoa!"}]$j$::jsonb,
  $j$https://cdn.hstatic.net/files/200001224249/file/screenshot_2026-11-10_190334_e0e528a4dc20454f8bf36347580ce9cb.png$j$, 6, 'Cây Cảnh Miền Tây',
  '[]'::jsonb, $j$["Sa Đéc Flower Half Marathon", "giải chạy", "Làng hoa Sa Đéc", "sự kiện"]$j$::jsonb,
